 * Helpers for detecting private, loopback and otherwise non-public network
 * hosts. These are used to guard against SSRF when resolving remote Spectral
 * ruleset `extends` targets.
 */

const parseIPv4 = (host: string): number[] | null => {
  const parts = host.split('.');
  if (parts.length !== 4) {
    return null;
  }

  const octets: number[] = [];
  for (const part of parts) {
    // Reject empty segments, non-digit characters and leading-zero ambiguity is
    // tolerated but the value must be a valid 0-255 octet.
    if (!/^\d+$/.test(part)) {
      return null;
    }
    const value = Number(part);
    if (value < 0 || value > 255) {
      return null;
    }
    octets.push(value);
  }

  return octets;
};

const isPrivateIPv4 = (host: string): boolean => {
  const octets = parseIPv4(host);
  if (!octets) {
    return false;
  }

  const [a, b] = octets;

  // Loopback 127.0.0.0/8
  if (a === 127) {
    return true;
  }
  // Private 10.0.0.0/8
  if (a === 10) {
    return true;
  }
  // Private 172.16.0.0/12 (172.16.x.x - 172.31.x.x)
  if (a === 172 && b >= 16 && b <= 31) {
    return true;
  }
  // Private 192.168.0.0/16
  if (a === 192 && b === 168) {
    return true;
  }
  // Link-local 169.254.0.0/16
  if (a === 169 && b === 254) {
    return true;
  }

  return false;
};

const isPrivateIPv6 = (host: string): boolean => {
  // IPv6 loopback.
  if (host === '::1') {
    return true;
  }

  if (!host.includes(':')) {
    return false;
  }

  // Unique local addresses fc00::/7 — the first byte is 0xfc or 0xfd, so the
  // leading hextet falls in the 0xfc00..0xfdff range.
  const firstGroup = host.split(':')[0];
  if (!/^[0-9a-f]{1,4}$/.test(firstGroup)) {
    return false;
  }
  const value = parseInt(firstGroup, 16);
  return value >= 0xfc00 && value <= 0xfdff;
};

/**
 * Determines whether the given hostname or IP address string refers to a
 * private, loopback or otherwise non-publicly-routable host.
 */
export const isPrivateOrLoopbackHost = (host: string): boolean => {
  if (!host) {
    return false;
  }

  let normalized = host.trim().toLowerCase();
  if (!normalized) {
    return false;
  }

  // Strip IPv6 bracket notation, e.g. "[::1]".
  if (normalized.startsWith('[') && normalized.endsWith(']')) {
    normalized = normalized.slice(1, -1);
  }

  // localhost and any of its subdomains, e.g. "app.localhost".
  if (normalized === 'localhost' || normalized.endsWith('.localhost')) {
    return true;
  }

  if (isPrivateIPv4(normalized)) {
    return true;
  }

  if (isPrivateIPv6(normalized)) {
    return true;
  }

  return false;
};
