/**
 * Validates the content of a Spectral ruleset before it is trusted by the app.
 *
 * The goal is to reject rulesets that could be used maliciously — prototype
 * pollution via crafted rule/property names, arbitrary custom `functions`
 * (which execute code), or `documentationUrl`s that point at non-https
 * locations — while still accepting the full range of legitimate rulesets.
 */

export type ValidationResult =
  | { isValid: true }
  | { isValid: false; error: string };

/**
 * Normalizes a value to an array: `undefined` becomes `[]`, an existing array
 * is returned unchanged and any other value is wrapped in a single-element
 * array.
 */
export const toArray = <T>(value: T | T[] | undefined): T[] => {
  if (value === undefined) {
    return [];
  }
  return Array.isArray(value) ? value : [value];
};

// Top-level keys we understand and consider safe. Notably `functions` is
// excluded because custom functions execute arbitrary code.
const ALLOWED_TOP_LEVEL_KEYS = new Set([
  'extends',
  'rules',
  'documentationUrl',
  'aliases',
  'overrides',
  'formats',
  'parserOptions',
]);

// Valid Spectral severity shorthands for a rule body.
const SEVERITY_STRINGS = new Set(['error', 'warn', 'info', 'hint', 'off']);

// Built-in Spectral functions that may be referenced from `then.function`.
const BUILT_IN_FUNCTIONS = new Set([
  'alphabetical',
  'casing',
  'defined',
  'enumeration',
  'falsy',
  'length',
  'pattern',
  'schema',
  'truthy',
  'typedEnum',
  'undefined',
  'unreferencedReusableObject',
  'or',
  'xor',
]);

// Tokens that could be used to trigger prototype pollution.
const PROTO_POLLUTION_TOKENS = ['__proto__', 'prototype', 'constructor'];

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const containsProtoToken = (value: string): boolean =>
  PROTO_POLLUTION_TOKENS.some(token => value.includes(token));

const invalid = (error: string): ValidationResult => ({ isValid: false, error });

const validateDocumentationUrl = (value: unknown): ValidationResult | null => {
  // Non-string documentationUrl values are skipped.
  if (typeof value !== 'string') {
    return null;
  }

  try {
    const url = new URL(value);
    if (url.protocol !== 'https:') {
      return invalid(`"documentationUrl" must use https: received "${value}"`);
    }
  } catch {
    return invalid(`"documentationUrl" is not a valid https URL: "${value}"`);
  }

  return null;
};

const validateGiven = (given: unknown): ValidationResult | null => {
  const entries = Array.isArray(given) ? given : [given];
  for (const entry of entries) {
    // Non-string given values are skipped (not checked).
    if (typeof entry !== 'string') {
      continue;
    }
    if (containsProtoToken(entry)) {
      return invalid(`"given" contains a disallowed token: "${entry}"`);
    }
  }
  return null;
};

const validateThenEntry = (then: unknown): ValidationResult | null => {
  // Non-object entries in a `then` array are skipped.
  if (!isPlainObject(then)) {
    return null;
  }

  const field = then.field;
  if (typeof field === 'string') {
    if (
      containsProtoToken(field) ||
      field.includes('.') ||
      field.includes('[') ||
      field.includes(']')
    ) {
      return invalid(`"then.field" contains a disallowed field name: "${field}"`);
    }
  }

  if ('function' in then) {
    const fn = then.function;
    if (typeof fn !== 'string' || !BUILT_IN_FUNCTIONS.has(fn)) {
      return invalid(`"then.function" is not an allowed built-in function: "${String(fn)}"`);
    }
  }

  return null;
};

const validateRuleBody = (name: string, body: unknown): ValidationResult | null => {
  // Boolean and severity-string shorthands are always allowed.
  if (typeof body === 'boolean') {
    return null;
  }
  if (typeof body === 'string') {
    if (SEVERITY_STRINGS.has(body)) {
      return null;
    }
    return invalid(`Rule "${name}" must be an object, boolean, or severity string`);
  }
  if (!isPlainObject(body)) {
    return invalid(`Rule "${name}" must be an object, boolean, or severity string`);
  }

  if ('given' in body) {
    const givenResult = validateGiven(body.given);
    if (givenResult) {
      return givenResult;
    }
  }

  if ('then' in body) {
    const thenEntries = Array.isArray(body.then) ? body.then : [body.then];
    for (const thenEntry of thenEntries) {
      const thenResult = validateThenEntry(thenEntry);
      if (thenResult) {
        return thenResult;
      }
    }
  }

  if ('documentationUrl' in body) {
    const docResult = validateDocumentationUrl(body.documentationUrl);
    if (docResult) {
      return docResult;
    }
  }

  return null;
};

const validateRules = (rules: unknown): ValidationResult | null => {
  if (!isPlainObject(rules)) {
    return invalid('"rules" must be an object');
  }

  for (const name of Object.keys(rules)) {
    const body = rules[name];

    // Reject prototype-polluting rule names when the body is an object.
    if (PROTO_POLLUTION_TOKENS.includes(name) && isPlainObject(body)) {
      return invalid(`Rule name "${name}" is not allowed`);
    }

    const bodyResult = validateRuleBody(name, body);
    if (bodyResult) {
      return bodyResult;
    }
  }

  return null;
};

const validateExtends = (value: unknown): ValidationResult | null => {
  for (const entry of toArray(value)) {
    if (typeof entry !== 'string') {
      return invalid('"extends" entries must be strings');
    }
  }
  return null;
};

/**
 * Validates the string content of a Spectral ruleset file.
 */
export const validateSpectralRuleset = (content: string): ValidationResult => {
  if (!content || !content.trim()) {
    return invalid('Ruleset is empty');
  }

  let parsed: unknown;
  try {
    parsed = YAML.parse(content);
  } catch {
    return invalid('Ruleset could not be parsed as YAML or JSON');
  }

  if (!isPlainObject(parsed)) {
    return invalid('Ruleset must be an object');
  }

  const keys = Object.keys(parsed);
  if (keys.length === 0) {
    return invalid('Ruleset must declare at least one of "extends" or "rules"');
  }

  for (const key of keys) {
    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
      return invalid(`Unsupported top-level key: "${key}"`);
    }
  }

  if ('extends' in parsed) {
    const extendsResult = validateExtends(parsed.extends);
    if (extendsResult) {
      return extendsResult;
    }
  }

  if ('rules' in parsed) {
    const rulesResult = validateRules(parsed.rules);
    if (rulesResult) {
      return rulesResult;
    }
  }

  if ('documentationUrl' in parsed) {
    const docResult = validateDocumentationUrl(parsed.documentationUrl);
    if (docResult) {
      return docResult;
    }
  }

