/**
 * Bundles a Spectral ruleset into a single self-contained YAML document.
 *
 * Local file `extends` targets are recursively read and their rules merged into
 * the parent (the parent wins on name collisions). Built-in spectral
 * identifiers (e.g. `spectral:oas`) are preserved and de-duplicated. Remote
 * https `extends` targets are validated — with SSRF protections — and kept as
 * URLs in the output; their rule content is never merged into the bundle.
 */

const SPECTRAL_BUILT_INS = new Set([
  'spectral:oas',
  'spectral:asyncapi',
  'spectral:arazzo',
]);

